package com.hmdp.ai.infrastructure.dify;
import com.fasterxml.jackson.databind.JsonNode;
public final class DifyAppConfiguration {private final String host,scheme,path,secretRef,responseMode;private final int port,maxResponseBytes;private final boolean allowPrivate;public DifyAppConfiguration(JsonNode c){host=required(c,"allowedHost");scheme=c.path("scheme").asText("https");path=c.path("path").asText("/v1/workflows/run");secretRef=required(c,"secretRef");responseMode=c.path("responseMode").asText("blocking").toLowerCase();port=c.path("port").asInt(-1);maxResponseBytes=Math.max(4096,c.path("maxResponseBytes").asInt(2*1024*1024));allowPrivate=c.path("allowPrivateNetwork").asBoolean(false);}private String required(JsonNode c,String n){String v=c.path(n).asText();if(v.isEmpty())throw new IllegalArgumentException("DIFY_PROVIDER_NOT_CONFIGURED");return v;}public String getHost(){return host;}public String getScheme(){return scheme;}public String getPath(){return path;}public String getSecretRef(){return secretRef;}public String getResponseMode(){return responseMode;}public int getPort(){return port;}public int getMaxResponseBytes(){return maxResponseBytes;}public boolean isAllowPrivate(){return allowPrivate;}}
